//! Deferred local-only Telegram commands. No Gmail/Telegram/browser network.
async fn telegram_local_fixture()->(PgConnection,TelegramSettings,TelegramIdentity){let(mut c,_,_)=browser_command_fixture().await;let(settings,identity)=telegram_question_binding(&mut c).await;(c,settings,identity)}
async fn telegram_local_result(c:&mut PgConnection,update:i64)->Value{let request=Uuid::new_v5(&Uuid::NAMESPACE_URL,format!("telegram:22:{update}").as_bytes());sqlx::query_scalar("SELECT result FROM agent_operations WHERE key=$1").bind(format!("telegram:11:{request}")).fetch_one(c).await.unwrap()}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_local_apply_saves_only_preview_audit_without_fetch_packet_or_apply_authority(){
 let(mut c,settings,identity)=telegram_local_fixture().await;let before=browser_snapshot(&mut c).await;let packets:i64=sqlx::query_scalar("SELECT count(*) FROM application_packets").fetch_one(&mut c).await.unwrap();let update=telegram_update(400,"/apply https://wellfound.com/jobs/fictional?token=PRIVATE_QUERY_CANARY");assert!(telegram_answer_update(&mut c,&settings,&identity,update.clone()).await.unwrap());let result=telegram_local_result(&mut c,400).await;assert_eq!(result["ok"],true);assert_eq!(result["data"]["platform"],"wellfound");assert_eq!(result["data"]["page_inspected"],false);assert_eq!(result["data"]["submitted"],false);assert!(result["data"]["url"].as_str().unwrap().contains("PRIVATE_QUERY_CANARY"));assert_eq!(browser_snapshot(&mut c).await,before);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM application_packets").fetch_one(&mut c).await.unwrap(),packets);assert!(!telegram_answer_update(&mut c,&settings,&identity,update).await.unwrap());assert_eq!(telegram_local_result(&mut c,400).await,result);let reply:String=sqlx::query_scalar("SELECT reply FROM agent_telegram_deliveries WHERE update_id=400").fetch_one(&mut c).await.unwrap();assert!(reply.contains("URL preview saved (wellfound)"));assert!(!reply.contains("PRIVATE_QUERY_CANARY"));assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'apply_budget:') OR starts_with(key,'chr_cmd:') OR starts_with(key,'fill_plan:')").fetch_one(&mut c).await.unwrap(),0);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_local_preview_disabled_policy_is_audited_denial_not_execution(){
 let(mut c,settings,identity)=telegram_local_fixture().await;sqlx::query("INSERT INTO agent_policies(key,version,preferences) VALUES('primary',7,$1)").bind(json!({"default":"approve","platforms":{"wellfound":"disabled"}})).execute(&mut c).await.unwrap();let before=browser_snapshot(&mut c).await;assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_update(410,"/apply https://wellfound.com/jobs/fictional")).await.unwrap());let result=telegram_local_result(&mut c,410).await;assert_eq!(result["ok"],false);assert_eq!(result["error_code"],"connection_disabled");assert_eq!(browser_snapshot(&mut c).await,before);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT next_update_id FROM agent_telegram_state WHERE key='primary'").fetch_one(&mut c).await.unwrap(),411);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_local_reset_clears_only_bot_selection_with_audit_and_preserves_shared_owner_memory_and_spent_history(){
 let(mut c,settings,identity)=telegram_local_fixture().await;let key=automated_apply_agents::telegram_local::context_key(11);let old=json!({"conversation_id":Uuid::new_v4(),"job_ids":[Uuid::new_v4()],"selected_job_id":Uuid::new_v4(),"project_id":"previous","clarification":"saved","history":[{"category":"JOB_SEARCH"}]});browser_save(&mut c,&key,old.clone()).await;let owner=json!({"messages":["PRIVATE_MEMORY_CANARY"],"campaign_ids":["retained"],"expires_at":"2099-01-01T00:00:00Z"});browser_save(&mut c,"agent_conversation:primary",owner.clone()).await;let spent=json!({"admissions":["spent-1","spent-2","spent-3"]});browser_save(&mut c,"apply_budget:naukri:retained",spent.clone()).await;let before=browser_snapshot(&mut c).await;assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_update(420,"/reset")).await.unwrap());let reset=browser_pref(&mut c,&key).await;assert_ne!(reset["conversation_id"],old["conversation_id"]);assert_eq!(reset["history"],json!([]));assert_eq!(reset["job_ids"],json!([]));assert_eq!(reset["selected_job_id"],Value::Null);assert_eq!(reset["project_id"],Value::Null);assert_eq!(reset["clarification"],Value::Null);let ttl=chrono::DateTime::parse_from_rfc3339(reset["expires_at"].as_str().unwrap()).unwrap();assert!(ttl>chrono::Utc::now());assert!(ttl<chrono::Utc::now()+chrono::Duration::minutes(11));assert_eq!(browser_pref(&mut c,"agent_conversation:primary").await,owner);assert_eq!(browser_pref(&mut c,"apply_budget:naukri:retained").await,spent);let after=browser_snapshot(&mut c).await;for(k,v)in before.as_object().unwrap(){if k!=&key{assert_eq!(&after[k],v,"{k}");}}assert_eq!(telegram_local_result(&mut c,420).await["data"]["status"],"context_reset");
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_local_suppressed_reset_write_rolls_back_memory_audit_offset_and_outbox(){
 let(mut c,settings,identity)=telegram_local_fixture().await;let key=automated_apply_agents::telegram_local::context_key(11);let old=json!({"job_ids":["retained"]});browser_save(&mut c,&key,old.clone()).await;sqlx::raw_sql("CREATE FUNCTION fixture_telegram_reset_suppress() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF starts_with(NEW.key,'telegram_context_') THEN RETURN NULL; END IF; RETURN NEW; END $$; CREATE TRIGGER fixture_telegram_reset_suppress BEFORE UPDATE ON owner_preferences FOR EACH ROW EXECUTE FUNCTION fixture_telegram_reset_suppress()").execute(&mut c).await.unwrap();let outcome=telegram_answer_update(&mut c,&settings,&identity,telegram_update(430,"/reset")).await;sqlx::raw_sql("DROP TRIGGER fixture_telegram_reset_suppress ON owner_preferences; DROP FUNCTION fixture_telegram_reset_suppress()").execute(&mut c).await.unwrap();assert_eq!(outcome.unwrap_err(),Failure("telegram_local_write_ack_failed"));assert_eq!(browser_pref(&mut c,&key).await,old);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT next_update_id FROM agent_telegram_state WHERE key='primary'").fetch_one(&mut c).await.unwrap(),0);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM rust_telegram_outbox WHERE update_id=430").fetch_one(&mut c).await.unwrap(),0);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM agent_operations WHERE actor='telegram:11'").fetch_one(&mut c).await.unwrap(),0);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_local_conflicting_retained_operation_never_resets_selection_or_adopts_old_intent(){
 let(mut c,settings,identity)=telegram_local_fixture().await;let key=automated_apply_agents::telegram_local::context_key(11);let old=json!({"job_ids":["retained"]});browser_save(&mut c,&key,old.clone()).await;let request=Uuid::new_v5(&Uuid::NAMESPACE_URL,b"telegram:22:440");let retained=json!({"status":"retained_unknown"});sqlx::query("INSERT INTO agent_operations(key,actor,command,payload_hash,result) VALUES($1,'telegram:11','conversation',$2,$3)").bind(format!("telegram:11:{request}")).bind("f".repeat(64)).bind(&retained).execute(&mut c).await.unwrap();assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_update(440,"/reset")).await.unwrap());assert_eq!(browser_pref(&mut c,&key).await,old);assert_eq!(telegram_local_result(&mut c,440).await,retained);let reply:String=sqlx::query_scalar("SELECT reply FROM agent_telegram_deliveries WHERE update_id=440").fetch_one(&mut c).await.unwrap();assert!(reply.contains("request_id_conflict"));
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_local_status_connections_avoid_owner_lock_and_never_expose_saved_token_or_identity(){
 let(mut c,settings,identity)=telegram_local_fixture().await;browser_save(&mut c,"gm54_account:1",json!({"status":"connected","account_email":"PRIVATE_EMAIL_CANARY@example.com","token":"PRIVATE_TOKEN_CANARY","last_verified_at":"2026-11-01T00:00:00Z"})).await;let mut values=queue_runtime_values();values.insert("GMAIL_LOCAL_ALLOWED_EMAILS".into(),json!(["fictional@example.com"]).to_string());let config=Configuration::from_values(&values).unwrap();let mut other=connection().await;let mut lock=other.begin().await.unwrap();sqlx::query("SELECT key FROM owner_preferences WHERE key='agent_conversation:primary' FOR UPDATE").execute(&mut *lock).await.unwrap();sqlx::query("SET lock_timeout='100ms'").execute(&mut c).await.unwrap();for(update,text)in [(450,"/status"),(451,"/connections")]{assert!(telegram::receive_configured(&mut c,&settings,&identity,&telegram_update(update,text),&Wake::default(),Some(&config)).await.unwrap());}lock.rollback().await.unwrap();let replies:Vec<String>=sqlx::query_scalar("SELECT reply FROM agent_telegram_deliveries ORDER BY update_id").fetch_all(&mut c).await.unwrap();assert!(replies[0].contains("current_query_succeeded"));assert!(replies[0].contains("not_probed_by_telegram"));assert!(replies[1].contains("saved Gmail state"));assert!(replies.iter().all(|s|!s.contains("PRIVATE_TOKEN_CANARY")&&!s.contains("PRIVATE_EMAIL_CANARY")));let connections=telegram_local_result(&mut c,451).await;let encoded=connections.to_string();assert!(!encoded.contains("PRIVATE_TOKEN_CANARY"));assert!(!encoded.contains("PRIVATE_EMAIL_CANARY"));
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_local_jobs_reports_stale_saved_discovery_without_new_provider_run(){
 let(mut c,settings,identity)=telegram_local_fixture().await;sqlx::raw_sql("CREATE TABLE IF NOT EXISTS automation_schedule(key varchar(20) PRIMARY KEY,enabled boolean NOT NULL,version integer NOT NULL DEFAULT 1,configuration jsonb NOT NULL DEFAULT '{}',next_run_at timestamptz,last_run_at timestamptz,heartbeat_at timestamptz); DELETE FROM automation_schedule; CREATE TABLE IF NOT EXISTS discovery_runs(id uuid PRIMARY KEY,source varchar(100),request_hash varchar(64),query_summary jsonb NOT NULL DEFAULT '{}',status varchar(50) NOT NULL DEFAULT 'running',rankings jsonb NOT NULL DEFAULT '[]',counts jsonb NOT NULL DEFAULT '{}',errors jsonb NOT NULL DEFAULT '[]',started_at timestamptz NOT NULL DEFAULT clock_timestamp(),finished_at timestamptz,provider_run_id varchar(255),usage jsonb NOT NULL DEFAULT '{}',idempotency_key varchar(100) UNIQUE); DELETE FROM discovery_runs").execute(&mut c).await.unwrap();sqlx::query("INSERT INTO automation_schedule(key,enabled) VALUES('primary',true)").execute(&mut c).await.unwrap();let run=Uuid::new_v4();sqlx::query("INSERT INTO discovery_runs(id,status,query_summary,started_at) VALUES($1,'running','{\"job_ids\":[]}', '2000-01-01T00:00:00Z')").bind(run).execute(&mut c).await.unwrap();assert!(telegram_answer_update(&mut c,&settings,&identity,telegram_update(460,"/jobs")).await.unwrap());let result=telegram_local_result(&mut c,460).await;assert_eq!(result["data"]["latest"]["status"],"recovery_required");assert_eq!(result["data"]["latest"]["job_count"],0);assert_eq!(result["data"]["discovery_executed"],false);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM discovery_runs").fetch_one(&mut c).await.unwrap(),1);let reply:String=sqlx::query_scalar("SELECT reply FROM agent_telegram_deliveries WHERE update_id=460").fetch_one(&mut c).await.unwrap();assert!(reply.contains("not a successful zero-match search"));assert!(reply.contains("No discovery executed"));
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn telegram_local_wrong_owner_forward_and_wrong_mention_cannot_reset_selection(){
 let(mut c,settings,identity)=telegram_local_fixture().await;let key=automated_apply_agents::telegram_local::context_key(11);let old=json!({"job_ids":["retained"]});browser_save(&mut c,&key,old.clone()).await;for index in 0..3{let mut update=telegram_update(470+index,"/reset");match index{0=>update["message"]["from"]["id"]=json!(999),1=>update["message"]["forward_origin"]=json!({"type":"user"}),_=>update["message"]["text"]=json!("/reset@wrong_bot")};let allowed=telegram_answer_update(&mut c,&settings,&identity,update).await.unwrap();assert_eq!(allowed,index==2);assert_eq!(browser_pref(&mut c,&key).await,old);}assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM agent_operations WHERE actor='telegram:11'").fetch_one(&mut c).await.unwrap(),0);
}
